*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page:        #0d1117;
  --bg-card:        #161b22;
  --bg-card-hover:  #1c2230;
  --border:         #30363d;
  --border-focus:   #58a6ff;
  --text-primary:   #e6edf3;
  --text-secondary: #8b949e;
  --accent:         #58a6ff;
  --accent-hover:   #79b8ff;
  --success-bg:     #0d2e1a;
  --success-border: #2ea043;
  --success-text:   #56d364;
  --error-bg:       #2d1315;
  --error-border:   #da3633;
  --error-text:     #ff7b72;
  --check-bg:       #58a6ff;
  --radius-sm:      4px;
  --radius-md:      8px;
  --radius-lg:      12px;
}

/* ── Skip link ──────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 999;
  transition: top 0.1s;
}

.skip-link:focus {
  top: 1rem;
}

/* ── Base ───────────────────────────────────────────────────────── */
body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Headings ───────────────────────────────────────────────────── */
h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.quiz-intro {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 0.95rem;
}

/* ── Form field card ────────────────────────────────────────────── */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-bottom: 1.25rem;
  transition: border-color 0.15s;
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* ── Fieldset / legend ──────────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-inline-size: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  padding: 0;
  margin-bottom: 0.5rem;
  line-height: 1.4;
  width: 100%;
}

.required-marker {
  color: var(--error-text);
  margin-left: 2px;
}

/* ── Help & error text ──────────────────────────────────────────── */
.help-text {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  margin-top: 0.25rem;
}

.error-text {
  font-size: 0.85rem;
  color: var(--error-text);
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: var(--radius-sm);
  padding: 0.4rem 0.75rem;
  margin-top: 0.75rem;
}

.error-text[hidden] {
  display: none;
}

/* ── Checkbox options ───────────────────────────────────────────── */
.checkbox-options {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.checkbox-option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.875rem;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}

.checkbox-option:hover {
  background: var(--bg-card-hover);
  border-color: var(--border);
}

/* ── Native checkbox styling ────────────────────────────────────── */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-page);
  cursor: pointer;
  position: relative;
  transition: background 0.12s, border-color 0.12s;
}

input[type="checkbox"]:hover {
  border-color: var(--accent);
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

input[type="checkbox"]:checked {
  background: var(--check-bg);
  border-color: var(--check-bg);
}

input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: 2px solid #000;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* Highlight the row when its checkbox is checked */
input[type="checkbox"]:checked + label {
  color: var(--accent-hover);
}

.checkbox-option:has(input[type="checkbox"]:checked) {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--accent) 35%, transparent);
}

label {
  cursor: pointer;
  font-size: 0.95rem;
  color: var(--text-primary);
  flex: 1;
}

/* ── Submit button ──────────────────────────────────────────────── */
.form-actions {
  margin-top: 1.75rem;
  display: flex;
  justify-content: flex-end;
}

button[type="submit"] {
  padding: 0.65rem 1.75rem;
  background: var(--accent);
  color: #000;
  font-size: 0.95rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

button[type="submit"]:active {
  transform: scale(0.98);
}

/* ── Quiz result live region ────────────────────────────────────── */
.quiz-result {
  margin-top: 1.5rem;
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  font-size: 0.95rem;
  line-height: 1.6;
}

.quiz-result[hidden] {
  display: none;
}

.quiz-result.is-success {
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  color: var(--success-text);
}

.quiz-result.is-error {
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  color: var(--error-text);
}

.quiz-result h2 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
}

.quiz-result p {
  color: inherit;
}

.score-highlight {
  font-size: 1.5rem;
  font-weight: 700;
  display: block;
  margin-bottom: 0.25rem;
}

/* ── Forced colors (high-contrast mode) ─────────────────────────── */
@media (forced-colors: active) {
  input[type="checkbox"] {
    forced-color-adjust: auto;
  }

  .form-field {
    border: 1px solid ButtonText;
  }

  button[type="submit"] {
    forced-color-adjust: auto;
  }
}

/* ── Reduced motion ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
  }
}

/* ── Reflow / narrow viewport ───────────────────────────────────── */
@media (max-width: 420px) {
  .form-field {
    padding: 1rem;
  }

  .form-actions {
    justify-content: stretch;
  }

  button[type="submit"] {
    width: 100%;
    text-align: center;
  }
}
