const ANSWERS = {
  q1: new Set(["java", "rust"]),         // Statically typed
  q2: new Set(["c", "rust", "cpp"]),     // Systems programming
  q3: new Set(["haskell", "javascript", "python"]), // First-class functions
};

const form = document.getElementById("quiz-form");
const resultEl = document.getElementById("quiz-result");

/**
 * Returns the Set of checked values for a given question name.
 * @param {string} name - e.g. "q1"
 * @returns {Set<string>}
 */
function getChecked(name) {
  const checked = form.querySelectorAll(`input[name="${name}"]:checked`);
  return new Set(Array.from(checked, (el) => el.value));
}

/**
 * Returns true if two Sets contain exactly the same values.
 * @param {Set} a
 * @param {Set} b
 * @returns {boolean}
 */
function setsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const v of a) {
    if (!b.has(v)) return false;
  }
  return true;
}

/**
 * Shows or hides an error message, and marks the fieldset's first checkbox
 * as aria-invalid when invalid.
 * @param {string} questionId - e.g. "q1"
 * @param {boolean} invalid
 */
function setQuestionValidity(questionId, invalid) {
  const errorEl = document.getElementById(`${questionId}-error`);
  const fieldset = errorEl.closest("fieldset");
  const firstCheckbox = fieldset.querySelector("input[type='checkbox']");

  if (invalid) {
    errorEl.removeAttribute("hidden");
    firstCheckbox.setAttribute("aria-invalid", "true");
    // Ensure the fieldset links to the error
    const described = (fieldset.getAttribute("aria-describedby") || "").split(" ").filter(Boolean);
    if (!described.includes(`${questionId}-error`)) {
      fieldset.setAttribute("aria-describedby", described.join(" "));
    }
  } else {
    errorEl.setAttribute("hidden", "");
    firstCheckbox.removeAttribute("aria-invalid");
  }
}

/**
 * Clears validation state on change so users get live feedback as they fix errors.
 */
form.addEventListener("change", (e) => {
  const input = e.target;
  if (input.type !== "checkbox") return;

  const name = input.name; // "q1", "q2", or "q3"
  const checked = getChecked(name);
  if (checked.size > 0) {
    setQuestionValidity(name, false);
  }
});

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const questions = ["q1", "q2", "q3"];
  let firstInvalidFieldset = null;
  let allValid = true;

  // Validate: each question needs at least one selection
  for (const q of questions) {
    const checked = getChecked(q);
    const invalid = checked.size === 0;
    setQuestionValidity(q, invalid);

    if (invalid) {
      allValid = false;
      if (!firstInvalidFieldset) {
        firstInvalidFieldset = form.querySelector(`input[name="${q}"]`);
      }
    }
  }

  if (!allValid) {
    // Focus the first unanswered question
    firstInvalidFieldset.focus();
    return;
  }

  // Score the quiz
  let correct = 0;
  for (const q of questions) {
    const chosen = getChecked(q);
    if (setsEqual(chosen, ANSWERS[q])) {
      correct++;
    }
  }

  showResult(correct, questions.length);
  resultEl.focus();
});

