    : `You got ${correct} out of ${total} questions exactly right. Review your selections and try again!`;

  resultEl.innerHTML = `
    <h2>${label}</h2>
    <span class="score-highlight">${correct} / ${total}</span>
    <p>${detail}</p>
  `;

  resultEl.removeAttribute("hidden");
  resultEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
}
